#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>

#define ALWAYS_INLINE inline
#define LIKELY(x) __builtin_expect(!!(x), 1)
#define UNLIKELY(x) __builtin_expect(!!(x), 0)

struct lwan_value {
    char *value;
    size_t len;
};

static inline int32_t string_as_int32(const char *s) {
    int32_t i;
    memcpy(&i, s, sizeof(int32_t));
    return i;
}

static inline int16_t string_as_int16(const char *s) {
    int16_t i;
    memcpy(&i, s, sizeof(int16_t));
    return i;
}

#define MULTICHAR_CONSTANT_SMALL(a, b) ((int16_t)((a) | (b) << 8))
#define MULTICHAR_CONSTANT_L(a, b, c, d) ((int32_t)((a) | (b) << 8 | (c) << 16 | (d) << 24))
#define STRING_SWITCH_SMALL(s) switch (string_as_int16(s))
#define STRING_SWITCH_L(s) switch (string_as_int32(s) | 0x20202020)

#define N_HEADER_START 64

struct lwan_request_parser_helper {
    struct lwan_value *buffer;
    char *next_request;
    char **header_start;
    size_t n_header_start;
    struct lwan_value accept_encoding;
    struct lwan_value cookie;
    struct lwan_value query_string;
    struct lwan_value fragment;
    struct lwan_value authorization;
    struct lwan_value post_data;
    struct lwan_value content_type;
    struct lwan_value content_length;
    struct lwan_value connection;
    struct { struct lwan_value raw; time_t parsed; } if_modified_since;
    struct { struct lwan_value raw; off_t from, to; } range;
    time_t error_when_time;
    int error_when_n_packets;
    int urls_rewritten;
};

#define HEADER_LENGTH(hdr) \
    ({ \
        if (UNLIKELY(end - sizeof(hdr) + 1 < p)) \
            continue; \
        sizeof(hdr) - 1; \
    })

#define HEADER(hdr) \
    ({ \
        p += HEADER_LENGTH(hdr); \
        if (UNLIKELY(string_as_int16(p) != MULTICHAR_CONSTANT_SMALL(':', ' '))) \
            continue; \
        *end = '\0'; \
        char *value = p + sizeof(": ") - 1; \
        (struct lwan_value){.value = value, .len = (size_t)(end - value)}; \
    })

static bool parse_headers(struct lwan_request_parser_helper *helper, char *buffer)
{
    char *buffer_end = helper->buffer->value + helper->buffer->len;
    char **header_start = helper->header_start;
    char *p;
    size_t n_headers = 0;
    bool ret = false;

    for (p = buffer + 1; n_headers < N_HEADER_START && buffer_end > p;) {
        char *next_chr = p;
        char *next_hdr = memchr(next_chr, '\r', (size_t)(buffer_end - p));

        if (!next_hdr)
            goto process;

        if (next_chr == next_hdr) {
            STRING_SWITCH_SMALL(next_hdr) {
            case MULTICHAR_CONSTANT_SMALL('\r', '\n'):
                helper->next_request = next_hdr + 2;
            }
            goto process;
        }

        header_start[n_headers++] = next_chr;
        header_start[n_headers++] = next_hdr;

        p = next_hdr + 2;
    }

    goto out;

process:
    ret = true;

    for (size_t i = 0; i < n_headers; i += 2) {
        char *end = header_start[i + 1];
        p = header_start[i];

        STRING_SWITCH_L(p) {
        case MULTICHAR_CONSTANT_L('A', 'c', 'c', 'e'):
            p += HEADER_LENGTH("Accept");
            STRING_SWITCH_L(p) {
            case MULTICHAR_CONSTANT_L('-', 'E', 'n', 'c'):
                helper->accept_encoding = HEADER("-Encoding");
                break;
            }
            break;
        case MULTICHAR_CONSTANT_L('A', 'u', 't', 'h'):
            helper->authorization = HEADER("Authorization");
            break;
        case MULTICHAR_CONSTANT_L('C', 'o', 'n', 'n'):
            helper->connection = HEADER("Connection");
            break;
        case MULTICHAR_CONSTANT_L('C', 'o', 'n', 't'):
            p += HEADER_LENGTH("Content");
            STRING_SWITCH_L(p) {
            case MULTICHAR_CONSTANT_L('-', 'T', 'y', 'p'):
                helper->content_type = HEADER("-Type");
                break;
            case MULTICHAR_CONSTANT_L('-', 'L', 'e', 'n'):
                helper->content_length = HEADER("-Length");
                break;
            }
            break;
        case MULTICHAR_CONSTANT_L('C', 'o', 'o', 'k'):
            helper->cookie = HEADER("Cookie");
            break;
        case MULTICHAR_CONSTANT_L('I', 'f', '-', 'M'):
            helper->if_modified_since.raw = HEADER("If-Modified-Since");
            break;
        case MULTICHAR_CONSTANT_L('R', 'a', 'n', 'g'):
            helper->range.raw = HEADER("Range");
            break;
        }
    }

out:
    helper->n_header_start = n_headers;
    return ret;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);

    static char data_copy[32767] = {0};
    if (len > (long)sizeof(data_copy))
        len = (long)sizeof(data_copy);
    fread(data_copy, 1, len, f);
    fclose(f);

    struct lwan_value buf_val = {.value = data_copy, .len = (size_t)len};
    char *header_start[N_HEADER_START];
    struct lwan_request_parser_helper helper = {
        .buffer = &buf_val,
        .header_start = header_start,
    };

    char *buffer = data_copy;
    char *space = memchr(buffer, ' ', len);
    if (!space) return 0;
    buffer = space + 1;

    space = memchr(buffer, ' ', len - (buffer - data_copy));
    if (!space) return 0;
    buffer = space + 1;

    char *crlf = memchr(buffer, '\r', len - (buffer - data_copy));
    if (!crlf) return 0;
    buffer = crlf + 1;

    printf("Calling parse_headers with buffer at offset %ld\n", (long)(buffer - data_copy));
    printf("Buffer len: %zu\n", len - (size_t)(buffer - data_copy));

    bool result = parse_headers(&helper, buffer);
    printf("Result: %d, n_headers: %zu\n", result, helper.n_header_start);

    return 0;
}
'''

